1	import {
2	  Download,
3	  ExternalLink,
4	  File,
5	  FileImage,
6	  FileSpreadsheet,
7	  FileText,
8	} from "lucide-react";
9	import { useEffect, useState } from "react";
10	import { useTranslation } from "react-i18next";
11	import { toast } from "sonner";
12	import { AuthenticatedImage } from "@/components/ui/AuthenticatedImage";
13	import { Spinner } from "@/components/ui/spinner";
14	import { downloadMedia, openMedia } from "@/hooks/useMediaUrl";
15	import { DocumentFile } from "@/types/document";
16	import {
17	  formatFileSize,
18	  getFileKind,
19	  isImageAttachment,
20	} from "@/utils/attachmentUtils";
21	
22	/** Icon for a given file, picked from its name/MIME type. */
23	export const FileKindIcon = ({
24	  filename,
25	  mimeType,
26	  className = "w-4 h-4 text-muted-foreground",
27	}: {
28	  filename: string;
29	  mimeType?: string | null;
30	  className?: string;
31	}) => {
32	  const kind = getFileKind(filename, mimeType);
33	  const Icon =
34	    kind === "image"
35	      ? FileImage
36	      : kind === "sheet"
37	        ? FileSpreadsheet
38	        : kind === "file"
39	          ? File
40	          : FileText;
41	  return <Icon className={className} />;
42	};
43	
44	/** Small thumbnail (image) or file-type icon used in dialog file rows. */
45	export const FilePreview = ({
46	  filename,
47	  mimeType,
48	  src,
49	  file,
50	}: {
51	  filename: string;
52	  mimeType?: string | null;
53	  src?: string;
54	  file?: File;
55	}) => {
56	  const [previewUrl, setPreviewUrl] = useState<string | undefined>();
57	
58	  useEffect(() => {
59	    if (!file) {
60	      setPreviewUrl(undefined);
61	      return;
62	    }
63	    const url = URL.createObjectURL(file);
64	    setPreviewUrl(url);
65	    return () => URL.revokeObjectURL(url);
66	  }, [file]);
67	
68	  if (isImageAttachment({ filename, mimeType })) {
69	    return (
70	      <AuthenticatedImage
71	        src={src ?? previewUrl}
72	        alt={filename}
73	        className="w-9 h-9 rounded object-cover border shrink-0"
74	      />
75	    );
76	  }
77	  return (
78	    <span className="w-9 h-9 rounded border flex items-center justify-center shrink-0">
79	      <FileKindIcon filename={filename} mimeType={mimeType} />
80	    </span>
81	  );
82	};
83	
84	/** Read-only list of a document's files: uploaded files preview + download,
85	 *  external links open in a new tab. */
86	export const DocumentFileList = ({ files }: { files: DocumentFile[] }) => {
87	  const { t } = useTranslation(undefined, {
88	    keyPrefix: "sheet.member-sheet.documents.file",
89	  });
90	  const [openingId, setOpeningId] = useState<string | null>(null);
91	
92	  if (!files.length) return null;
93	
94	  const open = (f: DocumentFile) => {
95	    setOpeningId(f.id);
96	    void openMedia(f.url)
97	      .catch(() => toast.error(t("error-open")))
98	      .finally(() => setOpeningId(null));
99	  };
100	  const download = (f: DocumentFile) => {
101	    void downloadMedia(f.url, f.filename ?? "file").catch(() =>
102	      toast.error(t("error-open")),
103	    );
104	  };
105	
106	  return (
107	    <div className="mt-2 space-y-1.5">
108	      {files.map((f) =>
109	        f.kind === "link" ? (
110	          <a
111	            key={f.id}
112	            href={f.url}
113	            target="_blank"
114	            rel="noopener noreferrer"
115	            className="flex items-center gap-2 text-sm text-primary underline underline-offset-2 min-w-0"
116	            title={f.filename ?? f.url}
117	          >
118	            <ExternalLink className="w-4 h-4 shrink-0" />
119	            <span className="truncate">{f.filename || f.url}</span>
120	          </a>
121	        ) : (
122	          <div key={f.id} className="flex items-center gap-2 text-sm min-w-0">
123	            <button
124	              type="button"
125	              onClick={() => open(f)}
126	              className="flex items-center gap-2 min-w-0 flex-1 hover:underline text-left"
127	              title={f.filename ?? ""}
128	            >
129	              {openingId === f.id ? (
130	                <Spinner className="w-4 h-4 text-muted-foreground shrink-0" />
131	              ) : isImageAttachment({
132	                  filename: f.filename ?? "",
133	                  mimeType: f.mimeType,
134	                }) ? (
135	                <AuthenticatedImage
136	                  src={f.url}
137	                  alt={f.filename ?? ""}
138	                  className="w-9 h-9 rounded object-cover border shrink-0"
139	                />
140	              ) : (
141	                <FileKindIcon
142	                  filename={f.filename ?? ""}
143	                  mimeType={f.mimeType}
144	                />
145	              )}
146	              <span className="truncate">{f.filename || f.url}</span>
147	            </button>
148	            {f.size != null && (
149	              <span className="text-xs text-muted-foreground shrink-0">
150	                {formatFileSize(f.size)}
151	              </span>
152	            )}
153	            <button
154	              type="button"
155	              onClick={() => download(f)}
156	              className="text-muted-foreground hover:text-foreground shrink-0"
157	              title={t("download")}
158	              aria-label={t("download")}
159	            >
160	              <Download className="w-4 h-4" />
161	            </button>
162	          </div>
163	        ),
164	      )}
165	    </div>
166	  );
167	};
