1	import { useState, useEffect, useRef, useCallback, FormEvent } from "react";
2	import {
3	  Dialog,
4	  DialogContent,
5	  DialogHeader,
6	  DialogTitle,
7	  DialogFooter,
8	} from "@/components/ui/dialog";
9	import { Button } from "@/components/ui/button";
10	import { Input } from "@/components/ui/input";
11	import { Textarea } from "@/components/ui/textarea";
12	import { Label } from "@/components/ui/label";
13	import { PartialDatePicker } from "@/components/ui/partial-date-picker";
14	import { MultiSelect } from "@/components/ui/multi-select";
15	import { Spinner } from "@/components/ui/spinner";
16	import {
17	  CheckCircle,
18	  Download,
19	  Link as LinkIcon,
20	  Paperclip,
21	  Plus,
22	  X,
23	} from "lucide-react";
24	import { useDocumentStore } from "@/hooks/useDocumentStore";
25	import { useMemberStore } from "@/hooks/useMemberStore";
26	import { useAuthStore } from "@/hooks/useAuthStore";
27	import { ApiError } from "@/services/api";
28	import { getQuotaBucket } from "@/lib/quotaError";
29	import { toast } from "sonner";
30	import { useTranslation } from "react-i18next";
31	import { useUnsavedGuard } from "@/hooks/useUnsavedGuard";
32	import { getMemberOptions } from "@/utils/memberUtils";
33	import {
34	  ATTACHMENT_ACCEPT,
35	  attachmentError,
36	  formatFileSize,
37	  getBaseName,
38	} from "@/utils/attachmentUtils";
39	import { downloadMedia } from "@/hooks/useMediaUrl";
40	import { Document, DocumentFileOps, DocumentInput } from "@/types/document";
41	import { FilePreview } from "./DocumentFiles";
42	
43	interface Props {
44	  open: boolean;
45	  onOpenChange: (open: boolean) => void;
46	  document?: Document | null;
47	  initialMemberIds?: string[];
48	  onCreated?: (documentId: string) => void;
49	}
50	
51	interface ExistingFile {
52	  id: string;
53	  kind: "file" | "link";
54	  filename: string;
55	  url: string;
56	  mimeType: string | null;
57	  size: number | null;
58	}
59	
60	interface PendingFile {
61	  tempId: string;
62	  filename: string;
63	  file: File;
64	}
65	
66	interface PendingLink {
67	  tempId: string;
68	  url: string;
69	  label: string;
70	}
71	
72	const EMPTY_INPUT: DocumentInput = {
73	  title: "",
74	  description: "",
75	  documentDate: "",
76	};
77	
78	export const DocumentDialog = ({
79	  open,
80	  onOpenChange,
81	  document,
82	  initialMemberIds,
83	  onCreated,
84	}: Props) => {
85	  const { t, i18n } = useTranslation(undefined, {
86	    keyPrefix: "sheet.member-sheet.documents.dialog",
87	  });
88	  const { addDocument, updateDocument } = useDocumentStore();
89	  const { members } = useMemberStore();
90	  const maxFileBytes = useAuthStore(
91	    (state) => state.config?.media_limits.max_document_bytes,
92	  );
93	  const maxFileSize =
94	    maxFileBytes === undefined ? null : formatFileSize(maxFileBytes);
95	
96	  const [formData, setFormData] = useState<DocumentInput>(EMPTY_INPUT);
97	  const [selectedMemberIds, setSelectedMemberIds] = useState<string[]>([]);
98	  const [existing, setExisting] = useState<ExistingFile[]>([]);
99	  const [added, setAdded] = useState<PendingFile[]>([]);
100	  const [addedLinks, setAddedLinks] = useState<PendingLink[]>([]);
101	  const [showLinkForm, setShowLinkForm] = useState(false);
102	  const [linkUrl, setLinkUrl] = useState("");
103	  const [linkLabel, setLinkLabel] = useState("");
104	  const [fileError, setFileError] = useState<string | null>(null);
105	  const [submitting, setSubmitting] = useState(false);
106	  const [uploadProgress, setUploadProgress] = useState<{
107	    done: number;
108	    total: number;
109	  } | null>(null);
110	  const fileInputRef = useRef<HTMLInputElement>(null);
111	
112	  const [initialSnapshot, setInitialSnapshot] = useState<{
113	    formData: DocumentInput;
114	    selectedMemberIds: string[];
115	    existingJson: string;
116	  } | null>(null);
117	
118	  // Reset only when the dialog opens or the edited document changes — NOT on
119	  // every new `initialMemberIds` array reference. Callers routinely pass a
120	  // fresh array literal (e.g. `[member.id]`), so depending on its identity
121	  // would wipe in-progress edits on any parent re-render. A value-based key
122	  // keeps the reset stable across those re-renders.
123	  const initialMemberIdsKey = (initialMemberIds ?? []).join(" ");
124	
125	  useEffect(() => {
126	    setFileError(null);
127	    setAdded([]);
128	    setAddedLinks([]);
129	    setShowLinkForm(false);
130	    setLinkUrl("");
131	    setLinkLabel("");
132	    if (!open) {
133	      setInitialSnapshot(null);
134	      return;
135	    }
136	    if (document) {
137	      const files: ExistingFile[] = document.files.map((f) => ({
138	        id: f.id,
139	        kind: f.kind,
140	        filename: f.filename ?? "",
141	        url: f.url,
142	        mimeType: f.mimeType,
143	        size: f.size,
144	      }));
145	      const snap = {
146	        formData: {
147	          title: document.title,
148	          description: document.description ?? "",
149	          documentDate: document.documentDate ?? "",
150	        },
151	        selectedMemberIds: document.memberIds,
152	        existingJson: JSON.stringify(
153	          files.map((f) => ({ id: f.id, filename: f.filename })),
154	        ),
155	      };
156	      setInitialSnapshot(snap);
157	      setFormData(snap.formData);
158	      setSelectedMemberIds(snap.selectedMemberIds);
159	      setExisting(files);
160	    } else {
161	      const ids = initialMemberIds ?? [];
162	      setInitialSnapshot({
163	        formData: EMPTY_INPUT,
164	        selectedMemberIds: ids,
165	        existingJson: "[]",
166	      });
167	      setFormData(EMPTY_INPUT);
168	      setSelectedMemberIds(ids);
169	      setExisting([]);
170	    }
171	    // eslint-disable-next-line react-hooks/exhaustive-deps
172	  }, [document, initialMemberIdsKey, open]);
173	
174	  const handleFilesPicked = (fileList: FileList | null) => {
175	    if (!fileList) return;
176	    setFileError(null);
177	    let shouldDefaultTitle = !formData.title.trim();
178	    for (const file of Array.from(fileList)) {
179	      const err = attachmentError(file, maxFileBytes);
180	      if (err) {
181	        setFileError(t(`files.error-${err}`, { max: maxFileSize ?? "" }));
182	        continue;
183	      }
184	      setAdded((prev) => [
185	        ...prev,
186	        { tempId: crypto.randomUUID(), filename: file.name, file },
187	      ]);
188	      if (shouldDefaultTitle) {
189	        setFormData((prev) => ({ ...prev, title: getBaseName(file.name) }));
190	        shouldDefaultTitle = false;
191	      }
192	    }
193	    if (fileInputRef.current) fileInputRef.current.value = "";
194	  };
195	
196	  const addLink = () => {
197	    const url = linkUrl.trim();
198	    if (!url) return;
199	    setAddedLinks((prev) => [
200	      ...prev,
201	      { tempId: crypto.randomUUID(), url, label: linkLabel.trim() },
202	    ]);
203	    setLinkUrl("");
204	    setLinkLabel("");
205	    setShowLinkForm(false);
206	  };
207	
208	  const buildFileOps = (): DocumentFileOps => {
209	    const original = document?.files ?? [];
210	    const keptIds = new Set(existing.map((f) => f.id));
211	    const removedIds = original
212	      .filter((f) => !keptIds.has(f.id))
213	      .map((f) => f.id);
214	    const renamed = existing
215	      .filter((f) => {
216	        const orig = original.find((o) => o.id === f.id);
217	        return (
218	          orig &&
219	          (orig.filename ?? "") !== f.filename &&
220	          f.filename.trim() !== ""
221	        );
222	      })
223	      .map((f) => ({ id: f.id, filename: f.filename.trim() }));
224	    return {
225	      addedFiles: added.map((a) => ({
226	        filename: a.filename.trim() || "file",
227	        file: a.file,
228	      })),
229	      addedLinks: addedLinks.map((l) => ({
230	        url: l.url,
231	        label: l.label || undefined,
232	      })),
233	      removedIds,
234	      renamed,
235	    };
236	  };
237	
238	  const isDirty =
239	    initialSnapshot !== null &&
240	    (formData.title !== initialSnapshot.formData.title ||
241	      formData.description !== initialSnapshot.formData.description ||
242	      formData.documentDate !== initialSnapshot.formData.documentDate ||
243	      JSON.stringify(selectedMemberIds) !==
244	        JSON.stringify(initialSnapshot.selectedMemberIds) ||
245	      JSON.stringify(
246	        existing.map((f) => ({ id: f.id, filename: f.filename })),
247	      ) !== initialSnapshot.existingJson ||
248	      added.length > 0 ||
249	      addedLinks.length > 0);
250	
251	  const save = useCallback(async (): Promise<boolean> => {
252	    if (!formData.title.trim()) return false;
253	    setSubmitting(true);
254	    try {
255	      const ops = buildFileOps();
256	      const addedCount = ops.addedFiles.length;
257	      if (addedCount > 0) setUploadProgress({ done: 0, total: addedCount });
258	      const onFileProgress = (done: number, total: number) =>
259	        setUploadProgress({ done, total });
260	      if (document) {
261	        await updateDocument(
262	          document.id,
263	          formData,
264	          selectedMemberIds,
265	          ops,
266	          onFileProgress,
267	        );
268	      } else {
269	        const created = await addDocument(
270	          formData,
271	          selectedMemberIds,
272	          ops,
273	          onFileProgress,
274	        );
275	        if (created) onCreated?.(created.id);
276	      }
277	      onOpenChange(false);
278	      return true;
279	    } catch (err: unknown) {
280	      if (err instanceof ApiError && err.status === 413) {
281	        const bucket = getQuotaBucket(err.message);
282	        if (bucket) {
283	          toast.error(t(`files.error-quota-${bucket}`));
284	        } else {
285	          toast.error(t("files.error-size", { max: maxFileSize ?? "" }));
286	        }
287	      } else {
288	        toast.error(t("error-save"));
289	      }
290	      return false;
291	    } finally {
292	      setSubmitting(false);
293	      setUploadProgress(null);
294	    }
295	    // eslint-disable-next-line react-hooks/exhaustive-deps
296	  }, [
297	    document,
298	    formData,
299	    selectedMemberIds,
300	    existing,
301	    added,
302	    addedLinks,
303	    addDocument,
304	    updateDocument,
305	    onCreated,
306	    onOpenChange,
307	  ]);
308	
309	  const handleSubmit = (e: FormEvent) => {
310	    e.preventDefault();
311	    // Stop the submit from bubbling through the portal to the surrounding
312	    // member-edit form, which would save the member and close the sheet.
313	    e.stopPropagation();
314	    void save();
315	  };
316	
317	  useUnsavedGuard("document", isDirty, save);
318	
319	  const memberOptions = getMemberOptions(members, (name) =>
320	    i18n.t("common.nee", { name }),
321	  );
322	
323	  return (
324	    <Dialog open={open} onOpenChange={onOpenChange}>
325	      <DialogContent className="sm:max-w-150 max-h-[80vh] flex flex-col">
326	        <DialogHeader>
327	          <DialogTitle>
328	            {document ? t("edit-title") : t("add-title")}
329	          </DialogTitle>
330	        </DialogHeader>
331	        <form
332	          onSubmit={handleSubmit}
333	          className="space-y-4 flex flex-col flex-1 min-h-0"
334	        >
335	          <div className="space-y-4 py-4 px-1 flex-1 overflow-y-auto">
336	            <div className="space-y-2">
337	              <Label htmlFor="doc-title">{t("title")} *</Label>
338	              <Input
339	                id="doc-title"
340	                value={formData.title}
341	                onChange={(e) =>
342	                  setFormData({ ...formData, title: e.target.value })
343	                }
344	                placeholder={t("title-placeholder")}
345	                required
346	              />
347	            </div>
348	
349	            <div className="space-y-2">
350	              <Label htmlFor="doc-description">{t("description")}</Label>
351	              <Textarea
352	                id="doc-description"
353	                value={formData.description}
354	                onChange={(e) =>
355	                  setFormData({ ...formData, description: e.target.value })
356	                }
357	                placeholder={t("description-placeholder")}
358	                rows={3}
359	                className="resize-none"
360	              />
361	            </div>
362	
363	            <div className="space-y-2">
364	              <Label>{t("date")}</Label>
365	              <PartialDatePicker
366	                value={formData.documentDate || null}
367	                onChange={(value) =>
368	                  setFormData({ ...formData, documentDate: value ?? "" })
369	                }
370	                placeholder={t("date-placeholder")}
371	              />
372	            </div>
373	
374	            <div className="space-y-2">
375	              <Label>{t("people-mentioned")}</Label>
376	              <MultiSelect
377	                options={memberOptions}
378	                onValueChange={setSelectedMemberIds}
379	                defaultValue={selectedMemberIds}
380	                placeholder={t("people-mentioned-placeholder")}
381	                variant="inverted"
382	                maxCount={5}
383	                hideSelectedOptions
384	              />
385	              <p className="text-xs text-muted-foreground">
386	                {t("people-mentioned-description")}
387	              </p>
388	            </div>
389	
390	            {/* Files */}
391	            <div className="space-y-2">
392	              <div className="flex items-center justify-between">
393	                <Label>{t("files.heading")}</Label>
394	                <div className="flex gap-1">
395	                  <Button
396	                    type="button"
397	                    variant="ghost"
398	                    size="sm"
399	                    disabled={submitting}
400	                    onClick={() => fileInputRef.current?.click()}
401	                  >
402	                    <Plus />
403	                    {t("files.add-file")}
404	                  </Button>
405	                  <Button
406	                    type="button"
407	                    variant="ghost"
408	                    size="sm"
409	                    disabled={submitting}
410	                    onClick={() => setShowLinkForm(true)}
411	                  >
412	                    <LinkIcon />
413	                    {t("files.add-link")}
414	                  </Button>
415	                </div>
416	              </div>
417	              <input
418	                ref={fileInputRef}
419	                type="file"
420	                multiple
421	                accept={ATTACHMENT_ACCEPT}
422	                className="hidden"
423	                onChange={(e) => handleFilesPicked(e.target.files)}
424	              />
425	
426	              {existing.length === 0 &&
427	              added.length === 0 &&
428	              addedLinks.length === 0 ? (
429	                <p className="text-xs text-muted-foreground italic">
430	                  {t("files.empty")}
431	                </p>
432	              ) : (
433	                <div className="space-y-2">
434	                  {existing.map((f) => (
435	                    <div key={f.id} className="flex items-center gap-2">
436	                      {f.kind === "link" ? (
437	                        <span className="w-9 h-9 rounded border flex items-center justify-center shrink-0">
438	                          <LinkIcon className="w-4 h-4 text-muted-foreground" />
439	                        </span>
440	                      ) : (
441	                        <FilePreview
442	                          filename={f.filename}
443	                          mimeType={f.mimeType}
444	                          src={f.url}
445	                        />
446	                      )}
447	                      <Input
448	                        value={f.filename}
449	                        onChange={(e) =>
450	                          setExisting((prev) =>
451	                            prev.map((x) =>
452	                              x.id === f.id
453	                                ? { ...x, filename: e.target.value }
454	                                : x,
455	                            ),
456	                          )
457	                        }
458	                        className="h-8 flex-1"
459	                        aria-label={t("files.filename")}
460	                      />
461	                      {f.kind === "file" && (
462	                        <button
463	                          type="button"
464	                          onClick={() =>
465	                            void downloadMedia(f.url, f.filename).catch(() =>
466	                              toast.error(t("files.error-open")),
467	                            )
468	                          }
469	                          className="text-muted-foreground hover:text-foreground"
470	                          title={t("files.download")}
471	                          aria-label={t("files.download")}
472	                        >
473	                          <Download className="w-4 h-4" />
474	                        </button>
475	                      )}
476	                      <Button
477	                        type="button"
478	                        variant="ghost"
479	                        size="icon"
480	                        className="h-8 w-8"
481	                        title={t("files.remove")}
482	                        onClick={() =>
483	                          setExisting((prev) =>
484	                            prev.filter((x) => x.id !== f.id),
485	                          )
486	                        }
487	                      >
488	                        <X className="w-4 h-4" />
489	                      </Button>
490	                    </div>
491	                  ))}
492	
493	                  {added.map((a, i) => (
494	                    <div key={a.tempId} className="flex items-center gap-2">
495	                      <FilePreview
496	                        filename={a.filename}
497	                        mimeType={a.file.type}
498	                        file={a.file}
499	                      />
500	                      <Input
501	                        value={a.filename}
502	                        onChange={(e) =>
503	                          setAdded((prev) =>
504	                            prev.map((x) =>
505	                              x.tempId === a.tempId
506	                                ? { ...x, filename: e.target.value }
507	                                : x,
508	                            ),
509	                          )
510	                        }
511	                        className="h-8 flex-1"
512	                        aria-label={t("files.filename")}
513	                        disabled={submitting}
514	                      />
515	                      {!uploadProgress ? (
516	                        <span className="text-xs text-muted-foreground shrink-0">
517	                          {t("files.new")}
518	                        </span>
519	                      ) : i < uploadProgress.done ? (
