43	/** Stream the picked files into the staging area (reporting per-file progress)
44	 *  and build the atomic save payload referencing them. New files are staged
45	 *  *before* the save runs — and the save removes old files only after it
46	 *  commits — so a failed save never destroys the previous version. */
47	async function stageAndBuildPayload(
48	  treeId: string,
49	  input: DocumentInput,
50	  memberIds: string[],
51	  ops: DocumentFileOps,
52	  onFileProgress?: (uploaded: number, total: number) => void,
53	): Promise<DocumentSavePayload> {
54	  const total = ops.addedFiles.length;
55	  if (total > 0) onFileProgress?.(0, total);
56	  const attachedUploadIds: string[] = [];
57	  for (const [i, f] of ops.addedFiles.entries()) {
58	    const staged = await TreeService.stageDocumentUpload(
59	      treeId,
60	      f.file,
61	      f.filename,
62	    );
63	    attachedUploadIds.push(staged.id);
64	    onFileProgress?.(i + 1, total);
65	  }
66	  return {
67	    title: input.title,
68	    description: input.description || null,
69	    document_date: input.documentDate || null,
70	    member_ids: memberIds,
71	    attached_upload_ids: attachedUploadIds,
72	    added_links: ops.addedLinks.map((l) => ({
73	      id: crypto.randomUUID(),
74	      url: l.url,
75	      filename: l.label ?? null,
76	    })),
77	    removed_file_ids: ops.removedIds,
78	    renamed_files: ops.renamed,
