104	  getDocumentsForMember: (memberId: string) => {
105	    return get().documents.filter((d) => d.memberIds.includes(memberId));
106	  },
107	
108	  addDocument: async (
109	    input: DocumentInput,
110	    memberIds: string[],
111	    fileOps: DocumentFileOps = NO_OPS,
112	    onFileProgress?: (uploaded: number, total: number) => void,
113	  ) => {
114	    const treeId = activeTreeId();
115	    if (!treeId) return null;
116	
117	    // Stage the files, then create the document with its metadata, people
118	    // links and attachments in one atomic request. A client-generated id makes
119	    // a retried create upsert instead of duplicating; a failure leaves nothing
120	    // behind, so there is no orphaned row to roll back.
121	    const documentId = crypto.randomUUID();
122	    const payload = await stageAndBuildPayload(
