136	
137	  updateDocument: async (
138	    id: string,
139	    input: DocumentInput,
140	    memberIds: string[],
141	    fileOps: DocumentFileOps = NO_OPS,
142	    onFileProgress?: (uploaded: number, total: number) => void,
143	  ) => {
144	    const treeId = activeTreeId();
145	    if (!treeId) return;
146	
147	    // Stage new files first, then apply the metadata, member and file changes
148	    // in one atomic request; old files are removed only once it commits, so a
149	    // failed edit leaves the previous valid document untouched.
150	    const payload = await stageAndBuildPayload(
151	      treeId,
152	      input,
153	      memberIds,
154	      fileOps,
155	      onFileProgress,
156	    );
157	    await TreeService.saveDocument(treeId, id, payload);
158	
159	    await get().refreshDocuments(treeId);
160	    if (touchesMedia(fileOps)) useStorageStore.getState().refreshStorageUsage();
161	    invalidateActivityView();
