55	interface RequestOptions {
56	  params?: Record<string, string | number | boolean | undefined | null>;
57	  body?: unknown;
58	  formData?: FormData;
59	  raw?: boolean;
60	  signal?: AbortSignal;
61	}
62	
63	function buildUrl(path: string, params?: RequestOptions["params"]): string {
64	  const url = `${API_BASE}${path}`;
65	  if (!params) return url;
66	  const search = new URLSearchParams();
67	  Object.entries(params).forEach(([key, value]) => {
68	    if (value !== undefined && value !== null)
69	      search.append(key, String(value));
70	  });
71	  const qs = search.toString();
72	  return qs ? `${url}?${qs}` : url;
73	}
74	
75	async function request<T>(
76	  method: string,
77	  path: string,
78	  options: RequestOptions = {},
79	): Promise<T> {
80	  const headers: Record<string, string> = {};
81	  if (authToken) headers["Authorization"] = `Bearer ${authToken}`;
82	  if (publicTreeToken) headers["X-Public-Tree-Token"] = publicTreeToken;
83	
84	  let payload: BodyInit | undefined;
85	  if (options.formData) {
86	    payload = options.formData;
87	  } else if (options.body !== undefined) {
88	    headers["Content-Type"] = "application/json";
89	    payload = JSON.stringify(options.body);
90	  }
91	
92	  const response = await fetch(buildUrl(path, options.params), {
93	    method,
94	    headers,
95	    body: payload,
96	    signal: options.signal,
97	  });
98	
99	  if (response.status === 401) {
100	    unauthorizedHandler?.();
101	  }
102	
103	  if (!response.ok) {
104	    let detail = response.statusText;
105	    try {
106	      const data = await response.json();
107	      detail = data.detail || detail;
108	    } catch {
109	      // non-JSON error body
110	    }
111	    throw new ApiError(response.status, detail);
112	  }
113	
114	  if (options.raw) return response as unknown as T;
115	  if (response.status === 204) return undefined as T;
116	  return (await response.json()) as T;
117	}
