2	import { useGalleryStore } from "@/hooks/useGalleryStore";
3	import { useStorageStore } from "@/hooks/useStorageStore";
4	import { invalidateActivityView } from "@/hooks/invalidateDerivedViews";
5	import { ApiError } from "@/services/api";
6	import { getQuotaBucket, quotaToastKey } from "@/lib/quotaError";
7	import { getBaseName } from "@/utils/attachmentUtils";
8	import { toast } from "sonner";
9	import { useTranslation } from "react-i18next";
10	
11	export type UploadStatus = "queued" | "uploading" | "done" | "failed";
12	
13	export interface UploadQueueItem {
14	  id: string;
15	  file: File;
16	  name: string;
17	  thumbnailUrl: string;
18	  status: UploadStatus;
19	  errorKey?: string;
20	}
21	
22	interface UploadQueueState {
23	  items: UploadQueueItem[];
24	  enqueue: (files: File[]) => void;
25	  retry: (id: string) => void;
26	  cancel: (id: string) => void;
27	  clearCompleted: () => void;
28	  total: number;
29	  doneCount: number;
30	  isActive: boolean;
31	}
32	
33	const MAX_CONCURRENT = 3;
34	
35	// How long the panel lingers after every upload finishes successfully before
36	// it dismisses itself, giving the user a moment to see the completed state.
37	const AUTO_DISMISS_MS = 2500;
38	
39	function mapErrorToKey(err: unknown): string {
40	  if (err instanceof ApiError) {
41	    if (err.status === 413) {
42	      const bucket = getQuotaBucket(err.message);
43	      if (bucket) {
44	        return quotaToastKey(bucket);
45	      }
46	      return "toast-error-image-too-large";
47	    }
48	    if (err.status === 400) {
49	      return "toast-error-image-unsupported";
50	    }
51	  }
52	  return "toast-error-image-upload";
53	}
54	
55	export function useUploadQueue(): UploadQueueState {
56	  const { t } = useTranslation(undefined, { keyPrefix: "gallery-view.view" });
57	  const [items, setItemsState] = useState<UploadQueueItem[]>([]);
58	  // Ref is the source of truth for the worker; state is for rendering only.
59	  const itemsRef = useRef<UploadQueueItem[]>([]);
60	
61	  // Track object URLs for cleanup
62	  const objectUrlsRef = useRef<Set<string>>(new Set());
63	  // Prevent concurrent worker invocations
64	  const workerRunningRef = useRef(false);
65	
66	  const setItems = useCallback(
67	    (updater: (prev: UploadQueueItem[]) => UploadQueueItem[]) => {
68	      const next = updater(itemsRef.current);
69	      itemsRef.current = next;
70	      setItemsState(next);
71	    },
72	    [],
73	  );
74	
75	  // Revoke a set of object URLs
76	  const revokeUrls = useCallback((urls: string[]) => {
77	    for (const url of urls) {
78	      URL.revokeObjectURL(url);
79	      objectUrlsRef.current.delete(url);
80	    }
81	  }, []);
82	
83	  // Cleanup on unmount
84	  useEffect(() => {
85	    return () => {
86	      for (const url of objectUrlsRef.current) {
87	        URL.revokeObjectURL(url);
88	      }
89	      objectUrlsRef.current.clear();
90	    };
91	  }, []);
92	
93	  const runWorker = useCallback(async () => {
94	    if (workerRunningRef.current) return;
95	    workerRunningRef.current = true;
96	
97	    try {
98	      while (true) {
99	        const snapshot = itemsRef.current;
100	
101	        const inFlight = snapshot.filter(
102	          (i) => i.status === "uploading",
103	        ).length;
104	        const queued = snapshot.filter((i) => i.status === "queued");
105	
106	        if (queued.length === 0 && inFlight === 0) {
107	          // All done — check if we need to refresh
108	          const hasDone = snapshot.some((i) => i.status === "done");
109	          const hasFailed = snapshot.some((i) => i.status === "failed");
110	
111	          if (hasDone) {
112	            // Batch refresh once
113	            await useGalleryStore.getState().refreshGalleryImages();
114	            useStorageStore.getState().refreshStorageUsage();
115	            invalidateActivityView();
116	
117	            if (hasFailed) {
118	              const doneCount = snapshot.filter(
119	                (i) => i.status === "done",
120	              ).length;
121	              const failedCount = snapshot.filter(
122	                (i) => i.status === "failed",
123	              ).length;
124	              toast.warning(
125	                t("upload-queue.summary-partial", {
126	                  done: doneCount,
127	                  failed: failedCount,
128	                }),
129	              );
130	            } else {
131	              toast.success(
132	                t("upload-queue.summary-success", {
133	                  count: snapshot.filter((i) => i.status === "done").length,
134	                }),
135	              );
136	            }
137	          }
138	          break;
139	        }
140	
141	        if (inFlight >= MAX_CONCURRENT || queued.length === 0) {
142	          // Wait a tick and re-check (items complete asynchronously)
143	          await new Promise<void>((resolve) => setTimeout(resolve, 100));
144	          continue;
145	        }
146	
147	        // Pick up to (MAX_CONCURRENT - inFlight) queued items
148	        const toStart = queued.slice(0, MAX_CONCURRENT - inFlight);
149	
150	        // Mark them uploading
151	        setItems((prev) =>
152	          prev.map((item) =>
153	            toStart.some((s) => s.id === item.id)
154	              ? { ...item, status: "uploading" as const }
155	              : item,
156	          ),
157	        );
158	
159	        // Process each concurrently without awaiting all (fire and track)
160	        for (const item of toStart) {
161	          (async () => {
162	            try {
163	              await useGalleryStore.getState().addGalleryImage(
164	                {
165	                  file: item.file,
166	                  title: getBaseName(item.name),
167	                  description: null,
168	                  linkedMemberIds: [],
169	                },
170	                { refresh: false },
171	              );
172	              setItems((prev) =>
173	                prev.map((i) =>
174	                  i.id === item.id ? { ...i, status: "done" as const } : i,
175	                ),
176	              );
177	            } catch (err: unknown) {
178	              const errorKey = mapErrorToKey(err);
179	              setItems((prev) =>
180	                prev.map((i) =>
181	                  i.id === item.id
182	                    ? { ...i, status: "failed" as const, errorKey }
183	                    : i,
184	                ),
185	              );
186	            }
187	          })();
188	        }
189	      }
190	    } finally {
191	      workerRunningRef.current = false;
192	    }
193	  }, [t, setItems]);
194	
195	  const enqueue = useCallback(
196	    (files: File[]) => {
197	      const imageFiles = files.filter((f) => f.type.startsWith("image/"));
198	      if (imageFiles.length === 0) return;
199	
200	      const newItems: UploadQueueItem[] = imageFiles.map((file) => {
201	        const thumbnailUrl = URL.createObjectURL(file);
202	        objectUrlsRef.current.add(thumbnailUrl);
203	        return {
204	          id: crypto.randomUUID(),
205	          file,
206	          name: file.name,
207	          thumbnailUrl,
208	          status: "queued" as const,
209	        };
210	      });
211	
212	      setItems((prev) => [...prev, ...newItems]);
213	
214	      // Kick the worker after state update
215	      setTimeout(() => runWorker(), 0);
216	    },
217	    [runWorker, setItems],
218	  );
219	
220	  const retry = useCallback(
221	    (id: string) => {
222	      setItems((prev) =>
223	        prev.map((item) =>
224	          item.id === id
225	            ? { ...item, status: "queued" as const, errorKey: undefined }
226	            : item,
227	        ),
228	      );
229	      setTimeout(() => runWorker(), 0);
230	    },
231	    [runWorker, setItems],
232	  );
233	
234	  const cancel = useCallback(
235	    (id: string) => {
236	      setItems((prev) => {
237	        const item = prev.find((i) => i.id === id);
238	        if (item && item.status === "queued") {
239	          revokeUrls([item.thumbnailUrl]);
240	          return prev.filter((i) => i.id !== id);
241	        }
242	        return prev;
243	      });
244	    },
245	    [revokeUrls, setItems],
246	  );
247	
248	  const clearCompleted = useCallback(() => {
249	    setItems((prev) => {
250	      const toRemove = prev.filter(
251	        (i) => i.status === "done" || i.status === "failed",
252	      );
253	      revokeUrls(toRemove.map((i) => i.thumbnailUrl));
254	      return prev.filter((i) => i.status !== "done" && i.status !== "failed");
255	    });
256	  }, [revokeUrls, setItems]);
257	
258	  // Auto-dismiss the panel once every upload has completed successfully. If any
259	  // upload failed we keep the panel open so the user can review and retry it.
260	  useEffect(() => {
261	    if (items.length === 0) return;
262	    const allDone = items.every((i) => i.status === "done");
263	    if (!allDone) return;
264	
265	    const timeout = setTimeout(clearCompleted, AUTO_DISMISS_MS);
266	    return () => clearTimeout(timeout);
267	  }, [items, clearCompleted]);
268	
269	  const total = items.length;
270	  const doneCount = items.filter(
271	    (i) => i.status === "done" || i.status === "failed",
272	  ).length;
273	  const isActive = items.some(
274	    (i) => i.status === "queued" || i.status === "uploading",
275	  );
276	
277	  return {
278	    items,
279	    enqueue,
280	    retry,
281	    cancel,
282	    clearCompleted,
283	    total,
284	    doneCount,
285	    isActive,
286	  };
287	}
