143	export const api = {
144	  get: <T>(path: string, params?: RequestOptions["params"]) =>
145	    request<T>("GET", path, { params }),
146	  post: <T>(path: string, body?: unknown, signal?: AbortSignal) =>
147	    request<T>("POST", path, { body, signal }),
148	  put: <T>(path: string, body?: unknown) => request<T>("PUT", path, { body }),
149	  patch: <T>(path: string, body?: unknown) =>
